  const order = await orderService.get(req.params.id);
  res.json({ id: order.id, status: order.status, total: order.total });
});

// web-bff — استجابة أوسع لنفس الطلب
app.get('/order/:id', async (req, res) => {
  const [order, shipment] = await Promise.all([
    orderService.get(req.params.id),
    shippingService.getByOrder(req.params.id),
  ]);
  res.json({ order, shipment, timeline: buildTimeline(order, shipment) });
});

// order.proto
service OrderService {
  rpc GetOrder (GetOrderRequest) returns (Order);
  rpc WatchStatus (GetOrderRequest) returns (stream StatusUpdate);
}

message GetOrderRequest { string order_id = 1; }
message Order { string order_id = 1; string status = 2; }

